data.prompt:
{"id": "intersection_crash_frequency", "name": "Expected intersection crash frequency", "kind": "rate", "unit": "crashes/yr", "aggregation": "sum", "scales": "street, network", "definition": "Expected crashes per year from a safety performance function, Empirical Bayes-adjusted with history", "source": "AASHTO 2010 Highway Safety Manual"}
{"id": "perceived_comfort", "name": "Perceived comfort", "kind": "ordinal", "unit": "1–5 Likert", "aggregation": "wmean:visitors", "scales": "person, street, block", "definition": "Rated comfort of a public space (protection, places to sit, stand, see, talk)", "source": "Gehl 2010 (twelve quality criteria)"}
{"id": "perceived_integrity", "name": "Perceived integrity (trustworthiness)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "Six items on whether the trustee adheres to acceptable principles and keeps promises", "source": "Mayer & Davis 1999 (ABI model)"}
{"id": "single_bidding_rate", "name": "Single-bidding rate", "kind": "ratio", "unit": "1", "aggregation": "ratio-of-sums:single_bid_contracts/contracts", "scales": "organisation, city, region, nation", "definition": "Share of competitive tenders receiving only one bid (a corruption-risk red flag)", "source": "Fazekas, Tóth & King 2016"}

{"id": "social_infrastructure_gap", "name": "Social infrastructure provision gap", "kind": "ratio", "unit": "1", "aggregation": "none", "scales": "neighbourhood,district,city", "definition": "(Standard provision per population − actual provision) / standard provision, by facility type", "source": "Local planning standards"}
{"id": "rockfall_hazard_rating", "name": "Rockfall Hazard Rating", "kind": "ordinal", "unit": "score 0–972 from 12 categories (3–81 each)", "aggregation": "max", "scales": "street,network", "definition": "Exponential scores for slope height, ditch, exposure, sight distance, geology, block size, climate and history, summed", "source": "Pierson 1990 (RHRS, Oregon DOT)"}
{"id": "pedestrian_crossing_delay", "name": "Pedestrian crossing delay", "kind": "duration", "unit": "s", "aggregation": "wmean:trips", "scales": "street", "definition": "Mean wait at a crossing; at signals d = (C − g)² / (2C)", "source": "HCM 2016"}
{"id": "traffic_conflict_rate", "name": "Traffic conflict rate", "kind": "rate", "unit": "serious conflicts per hour", "aggregation": "ratio-of-sums:conflicts/hours", "scales": "street", "definition": "Serious conflicts (time-to-collision or post-encroachment time below thresholds) observed per hour", "source": "Hydén 1987 (Swedish Traffic Conflict Technique)"}

{"id": "cso_spill_frequency", "name": "CSO spill frequency", "kind": "rate", "unit": "spills/yr", "aggregation": "sum", "scales": "network, city", "definition": "Number of combined sewer overflow events per year (with volume and duration)", "source": "EA Event Duration Monitoring; US EPA CSO Control Policy 1994"}
{"id": "hazard_intensity_measure", "name": "Hazard intensity measure", "kind": "physical", "unit": "units of the hazard (m flood depth, g PGA, m/s gust)", "aggregation": "max", "scales": "parcel,building,block,city", "definition": "Physical measure of a hazard at a site (flood depth, peak ground acceleration, gust speed, temperature)", "source": "UNDRR 2017 terminology; FEMA HAZUS"}
{"id": "transfer_penalty", "name": "Transfer penalty", "kind": "duration", "unit": "equivalent in-vehicle min", "aggregation": "none", "scales": "person, network", "definition": "Disutility of a transfer beyond its walking and waiting time, in equivalent in-vehicle minutes", "source": "Wardman 2004"}
{"id": "energy_not_supplied", "name": "Energy not supplied", "kind": "flow", "unit": "MWh per yr", "aggregation": "sum", "scales": "network,city,region", "definition": "Energy demanded but not delivered because of outages or rota load shedding", "source": "CIGRE; Billinton & Allan 1996"}

{"id": "news_perceived_walkability", "name": "Perceived walkability (NEWS)", "kind": "latent", "unit": "1–4 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood", "definition": "Neighborhood Environment Walkability Scale: subscales on density, mix, connectivity, infrastructure, aesthetics, safety", "source": "Saelens et al. 2003; Cerin et al. 2006 (NEWS-A)"}
{"id": "night_event_count", "name": "Night-time cultural events per week", "kind": "count", "unit": "events per week", "aggregation": "sum", "scales": "district,city", "definition": "Cultural events starting after 18:00 per week", "source": "GLA 2018 London at Night"}
{"id": "pefa_score", "name": "PEFA performance score", "kind": "ordinal", "unit": "grades A–D per indicator", "aggregation": "none", "scales": "city,region,nation", "definition": "31 indicators in seven pillars (credibility to audit) scored A–D by declared calibration", "source": "PEFA Framework 2016"}
{"id": "infrastructure_investment_gap", "name": "Infrastructure investment gap", "kind": "amount", "unit": "currency", "aggregation": "sum", "scales": "city, region, nation", "definition": "Investment need to a benchmark or target − projected investment on current trends", "source": "Global Infrastructure Hub 2017 (Infrastructure Outlook)"}

{"id": "japanese_proficiency_level", "name": "Japanese language proficiency level", "kind": "ordinal", "unit": "levels N5–N1 (JLPT)", "aggregation": "median", "scales": "person, organisation", "definition": "Certified level of Japanese proficiency (JLPT N5 lowest to N1 highest); business Japanese by BJT J5–J1+", "source": "Japan Foundation & JEES JLPT"}
{"id": "height_to_width_ratio", "name": "Street height-to-width ratio", "kind": "ratio", "unit": "1", "aggregation": "wmean:length", "scales": "street", "definition": "H/W = mean building height on both sides / street width wall to wall", "source": "Oke 1988; Ewing & Handy 2009"}
{"id": "benefit_shortfall_ratio", "name": "Benefit (demand) shortfall ratio", "kind": "ratio", "unit": "1", "aggregation": "recompute", "scales": "project", "definition": "(forecast − actual benefit or demand) / forecast", "source": "Flyvbjerg, Holm & Buhl 2005"}
{"id": "days_of_inventory_cover", "name": "Days of inventory cover", "kind": "duration", "unit": "days", "aggregation": "min", "scales": "firm,city,nation", "definition": "Stock on hand / mean daily consumption of a critical good", "source": "IEA 90-day stockholding rule; APICS"}

{"id": "seating_capacity", "name": "Seating capacity (primary and secondary)", "kind": "count", "unit": "seats", "aggregation": "sum", "scales": "street,block,neighbourhood", "definition": "Primary seats plus secondary seating (ledges, steps) counted at 1 seat per 0.6 m of sittable edge", "source": "Whyte 1980"}
{"id": "urban_primacy_index", "name": "Urban primacy index", "kind": "ratio", "unit": "1", "aggregation": "recompute", "scales": "region, nation", "definition": "Population of the largest city / urban population (or / the next three cities)", "source": "Jefferson 1939; Henderson 2003"}
{"id": "trust_in_government", "name": "Trust in (local) government", "kind": "ordinal", "unit": "0–10", "aggregation": "wmean:population", "scales": "city, region, nation", "definition": "'How much do you trust the local government?' on 0–10; share with high trust (6–10)", "source": "OECD 2021 Trust Survey; OECD 2017 Guidelines on Measuring Trust"}
{"id": "land_administration_quality_index", "name": "Quality of land administration index", "kind": "composite", "unit": "0–30", "aggregation": "none", "scales": "city,nation", "definition": "Sum of scores on reliability of infrastructure, transparency, coverage, dispute resolution and equal access", "source": "World Bank Doing Business 2020"}

{"id": "necessity_consistency", "name": "Consistency of necessity (fuzzy sets)", "kind": "ratio", "unit": "[0,1]", "aggregation": "recompute", "scales": "project", "definition": "Cons(Y ⊆ X) = Σ min(x_i, y_i) / Σ y_i", "source": "Ragin 2006"}
{"id": "measurement_invariance_level", "name": "Measurement invariance level", "kind": "ordinal", "unit": "levels: none, configural, metric, scalar, strict", "aggregation": "min", "scales": "project", "definition": "Highest level of equality of a measurement model across groups not rejected (e.g. ΔCFI ≤ 0.01)", "source": "Vandenberg & Lance 2000; Chen 2007"}
{"id": "activity_density", "name": "Activity density", "kind": "density", "unit": "(residents + jobs)/km²", "aggregation": "ratio-of-sums:residents_and_jobs/area", "scales": "block, neighbourhood, city", "definition": "(population + employment) / land area", "source": "Ewing & Cervero 2010"}
{"id": "high_tide_flooding_frequency", "name": "High-tide flooding frequency", "kind": "rate", "unit": "days per yr", "aggregation": "max", "scales": "street,neighbourhood,city", "definition": "Days per year with water level above a local minor-flood threshold at a tide gauge", "source": "Sweet et al. 2018 (NOAA)"}

{"id": "resident_attitude_to_tourism", "name": "Resident attitude to tourism (TIAS)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "neighbourhood, city", "definition": "Latent factors of the Tourism Impact Attitude Scale (27 items: costs and benefits)", "source": "Lankford & Howard 1994"}
{"id": "fuel_reserve_days", "name": "Fuel reserve days", "kind": "duration", "unit": "days", "aggregation": "min", "scales": "organisation,city,nation", "definition": "Stocks of fuel / average daily consumption", "source": "IEA emergency stock obligation (90 days)"}
{"id": "risk_rating", "name": "Risk rating", "kind": "ordinal", "unit": "levels (e.g. low, medium, high, extreme from a 5 × 5 matrix)", "aggregation": "max", "scales": "building, project, organisation, city", "definition": "Likelihood level × consequence level read from a declared risk matrix", "source": "ISO 31000:2018; IEC 31010:2019"}
{"id": "average_online_rating", "name": "Average online rating", "kind": "ordinal", "unit": "1–5 stars", "aggregation": "wmean:visitors", "scales": "firm, street, neighbourhood", "definition": "Mean star rating with count of reviews on a review platform", "source": "Luca 2016"}

{"id": "availability_ratio", "name": "Availability", "kind": "ratio", "unit": "[0,1]", "aggregation": "ratio-of-sums:uptime/total_time", "scales": "building,network,organisation", "definition": "A = MTBF / (MTBF + MTTR), or uptime / total time", "source": "IEC 60050-192"}
{"id": "project_outcome_rating", "name": "Project outcome rating", "kind": "ordinal", "unit": "6 levels: highly unsatisfactory–highly satisfactory", "aggregation": "median", "scales": "project, organisation", "definition": "Rating of a project's relevance, efficacy and efficiency against its objectives on a six-point scale", "source": "World Bank IEG 2017"}
{"id": "getis_ord_gi_star", "name": "Getis–Ord Gi* statistic", "kind": "spatial-statistic", "unit": "z-score", "aggregation": "recompute", "scales": "block, neighbourhood, city", "definition": "Gi* = (Σ_j w_ij x_j − x̄ Σ_j w_ij) / (s √[(n Σ w_ij² − (Σ w_ij)²)/(n − 1)])", "source": "Getis & Ord 1992; Ord & Getis 1995"}
{"id": "import_penetration_exposure", "name": "Import penetration exposure (shift-share)", "kind": "coefficient", "unit": "currency per worker", "aggregation": "wmean:workers", "scales": "city,metro,region", "definition": "ΔIPW_r = Σ_j (L_rj/L_r) ΔM_j / L_j: local exposure to import growth by industry", "source": "Autor, Dorn & Hanson 2013"}

{"id": "vendor_net_income", "name": "Street vendor net income", "kind": "flow", "unit": "currency/day", "aggregation": "median", "scales": "person,street,city", "definition": "Daily sales minus costs of goods, fees and transport for a vendor", "source": "WIEGO Informal Economy Monitoring Study 2014"}
{"id": "multidimensional_poverty_index", "name": "Multidimensional poverty index", "kind": "composite", "unit": "[0,1]", "aggregation": "decomposable", "scales": "household, neighbourhood, city, region, nation", "definition": "MPI = H × A: headcount of those deprived in ≥ 1/3 of weighted indicators × average intensity", "source": "Alkire & Foster 2011; UNDP–OPHI global MPI"}
{"id": "drainage_capacity_return_period", "name": "Drainage design return period", "kind": "duration", "unit": "yr (return period)", "aggregation": "min", "scales": "street,neighbourhood,city", "definition": "Return period of the design storm a drainage network conveys without surcharge or flooding", "source": "EN 752:2017"}
{"id": "theil_index", "name": "Theil index", "kind": "distribution", "unit": "nats", "aggregation": "decomposable", "scales": "neighbourhood, city, metro, region, nation", "definition": "T = (1/n) Σ_i (y_i/ȳ) ln(y_i/ȳ) = Σ_g s_g T_g + Σ_g s_g ln(ȳ_g/ȳ)", "source": "Theil 1967"}

{"id": "heat_exposure_person_days", "name": "Heat exposure (person-days)", "kind": "count", "unit": "person-days per yr", "aggregation": "sum", "scales": "neighbourhood,city,region", "definition": "Persons × days with heat index (or WBGT) above a declared threshold", "source": "Tuholske et al. 2021"}
{"id": "liquefaction_potential_index", "name": "Liquefaction potential index", "kind": "composite", "unit": "0–100", "aggregation": "max", "scales": "parcel,block,neighbourhood", "definition": "LPI = ∫_0^20 m F(z) w(z) dz, F = 1 − FS where FS < 1, w(z) = 10 − 0.5z", "source": "Iwasaki et al. 1978"}
{"id": "active_travel_time", "name": "Active travel time", "kind": "duration", "unit": "min/person/day", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "Mean minutes per day walking and cycling for transport", "source": "WHO HEAT 2017 (Kahlmeier et al.)"}
{"id": "cultural_intelligence_scale", "name": "Cultural intelligence scale (CQS)", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "20 items over metacognitive, cognitive, motivational and behavioural cultural intelligence", "source": "Ang et al. 2007"}

