{"id": "perceived_comfort", "name": "Perceived comfort", "kind": "ordinal", "unit": "1–5 Likert", "aggregation": "wmean:visitors", "scales": "person, street, block", "definition": "Rated comfort of a public space (protection, places to sit, stand, see, talk)", "source": "Gehl 2010 (twelve quality criteria)"}
