{"id": "single_bidding_rate", "name": "Single-bidding rate", "kind": "ratio", "unit": "1", "aggregation": "ratio-of-sums:single_bid_contracts/contracts", "scales": "organisation, city, region, nation", "definition": "Share of competitive tenders receiving only one bid (a corruption-risk red flag)", "source": "Fazekas, Tóth & King 2016"}

{"id": "market_stall_fee", "name": "Market stall fee", "kind": "price", "unit": "currency/day", "aggregation": "median", "scales": "street,district,city", "definition": "Daily fee charged for a stall or vending pitch", "source": "Municipal market regulations"}
{"id": "green_view_index", "name": "Green View Index", "kind": "ratio", "unit": "1", "aggregation": "wmean:length", "scales": "street,neighbourhood,district", "definition": "Share of vegetation pixels in street-level images sampled at points in several directions", "source": "Li et al. 2015"}
{"id": "sense_of_place", "name": "Sense of place", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "Attitudinal scale over place identity, attachment and dependence items", "source": "Jorgensen & Stedman 2001"}
{"id": "perceived_safety", "name": "Perceived safety", "kind": "ordinal", "unit": "1–4 (very safe – very unsafe)", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "'How safe do you feel walking alone in your area after dark?' (SDG 16.1.4)", "source": "SDG 16.1.4; UNODC"}

{"id": "perceived_distributive_justice", "name": "Perceived distributive justice", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation, city", "definition": "Four items on whether outcomes reflect effort, contribution and what is deserved", "source": "Colquitt 2001"}
{"id": "heritage_significance_rating", "name": "Heritage significance rating", "kind": "ordinal", "unit": "levels (exceptional, high, moderate, little) per value", "aggregation": "max", "scales": "building,street,district", "definition": "Assessment of aesthetic, historic, scientific, social and spiritual value for past, present and future generations", "source": "Burra Charter 2013 (Australia ICOMOS); Historic England 2008 Conservation Principles"}
{"id": "conversion_completions", "name": "Dwellings created by change of use", "kind": "flow", "unit": "dwellings per yr", "aggregation": "sum", "scales": "district,city,nation", "definition": "Net additional dwellings from conversion of non-residential buildings in the year", "source": "DLUHC net additional dwellings statistics"}
{"id": "global_power_city_index", "name": "Global Power City Index", "kind": "composite", "unit": "score", "aggregation": "none", "scales": "city", "definition": "Sum of normalised indicators in six functions: economy, R&D, cultural interaction, livability, environment, accessibility", "source": "Mori Memorial Foundation GPCI"}

{"id": "place_identity", "name": "Place identity", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood", "definition": "Subscale of place attachment: items on how much a place is part of oneself", "source": "Williams & Vaske 2003"}
{"id": "total_addressable_market", "name": "Total addressable market", "kind": "flow", "unit": "currency/yr", "aggregation": "sum", "scales": "city, region, nation", "definition": "Revenue if every potential customer bought: potential buyers × annual spend per buyer", "source": "Blank & Dorf 2012"}
{"id": "total_factor_productivity", "name": "Total factor productivity", "kind": "coefficient", "unit": "1 (index)", "aggregation": "recompute", "scales": "firm, region, nation", "definition": "Solow residual: ln A = ln Y − α ln K − (1−α) ln L", "source": "Solow 1957"}
{"id": "perceived_ability", "name": "Perceived ability (trustworthiness)", "kind": "latent", "unit": "1–5 Likert", "aggregation": "wmean:population", "scales": "person, organisation", "definition": "Six items on the trustee's skills and competence in the relevant domain", "source": "Mayer & Davis 1999 (ABI model)"}

{"id": "trust_in_science", "name": "Trust in science and experts", "kind": "latent", "unit": "index (high, medium, low)", "aggregation": "median", "scales": "person,nation", "definition": "Latent index from items on trust in scientists, doctors and science information", "source": "Wellcome Global Monitor 2018"}
{"id": "exposed_asset_value", "name": "Exposed asset value", "kind": "amount", "unit": "currency", "aggregation": "sum", "scales": "building,block,neighbourhood,city,region", "definition": "Replacement value of buildings and infrastructure within a hazard footprint", "source": "UNDRR 2017; GEM exposure models"}
{"id": "container_dwell_time", "name": "Container dwell time", "kind": "duration", "unit": "days", "aggregation": "median", "scales": "network,nation", "definition": "Days import containers stay in the terminal from discharge to gate-out", "source": "World Bank Container Port Performance Index"}
{"id": "wetland_area", "name": "Wetland area", "kind": "amount", "unit": "ha", "aggregation": "sum", "scales": "city,region", "definition": "Area of wetlands (natural and restored)", "source": "Ramsar; SDG 6.6.1"}

{"id": "pima_score", "name": "Public investment management assessment score", "kind": "ordinal", "unit": "15 institutions rated low–medium–high", "aggregation": "median", "scales": "city, nation", "definition": "Ratings of institutional design and effectiveness over planning, allocation and implementation of public investment", "source": "IMF 2018 PIMA Handbook"}
{"id": "benefit_concentration_coefficient", "name": "Concentration coefficient of public benefits", "kind": "distribution", "unit": "[−1,1]", "aggregation": "recompute", "scales": "city,region,nation", "definition": "C = 1 − 2∫ L_B(p) dp, benefits ranked by income", "source": "Lustig 2018 (CEQ); Kakwani 1977"}
{"id": "perceived_social_norm", "name": "Perceived social norm", "kind": "latent", "unit": "1–7 Likert", "aggregation": "wmean:population", "scales": "person, neighbourhood, city", "definition": "Mean of items on descriptive (what others do) and injunctive (what others approve) norms for a behaviour", "source": "Cialdini, Reno & Kallgren 1990"}
{"id": "protest_event_count", "name": "Protest event count", "kind": "count", "unit": "events per period", "aggregation": "sum", "scales": "neighbourhood,city,region,nation", "definition": "Number of protest events coded from news or event data in a period and area", "source": "Tilly 1978; Raleigh et al. 2010 (ACLED)"}
